cat > /work/layout.py << 'EOF'
import itertools, math
import plant as p

def rect_ok(plant, x0, y0, x1, y1, c):
    P = p.PLANTS[plant]
    zx0, zy0, zx1, zy1 = P['zone']
    if x0 < zx0 + c - 1e-9 or y0 < zy0 + c - 1e-9 or x1 > zx1 - c + 1e-9 or y1 > zy1 - c + 1e-9:
        return None
    for (fx0, fy0, fx1, fy1), psf, name in P['framing']:
        if x0 >= fx0 - 1e-9 and x1 <= fx1 + 1e-9 and y0 >= fy0 - 1e-9 and y1 <= fy1 + 1e-9:
            # intake separation 25 ft from frame outline
            for ix, iy in P['intakes']:
                dx = max(x0 - ix, 0, ix - x1); dy = max(y0 - iy, 0, iy - y1)
                if math.hypot(dx, dy) < 25.0 + 2.0:   # 25 ft + intake radius margin
                    return None
            return (psf, name)
    return None

def sep_ok(a, b, c):
    ax0, ay0, ax1, ay1 = a; bx0, by0, bx1, by1 = b
    gx = max(bx0 - ax1, ax0 - bx1); gy = max(by0 - ay1, ay0 - by1)
    return gx >= c - 1e-9 or gy >= c - 1e-9

def candidates(plant, model, step=1.0):
    t = p.TOWERS[model]; W, L, opwt, c = t[6], t[7], t[8], t[9]
    load = opwt / (W * L)
    P = p.PLANTS[plant]
    zx0, zy0, zx1, zy1 = P['zone']
    out = []
    for (w, l) in ((L, W), (W, L)):
        x = zx0 + c
        while x + w <= zx1 - c + 1e-9:
            y = zy0 + c
            while y + l <= zy1 - c + 1e-9:
                r = rect_ok(plant, x, y, x + w, y + l, c)
                if r and load <= r[0] + 1e-9:
                    out.append((x, y, x + w, y + l))
                y += step
            x += step
    return out, c

def max_cells(plant, model, target=None, step=1.0):
    cands, c = candidates(plant, model, step)
    best = []
    def rec(chosen, start):
        nonlocal best
        if len(chosen) > len(best):
            best = list(chosen)
            if target and len(best) >= target:
                return True
        for i in range(start, len(cands)):
            r = cands[i]
            if all(sep_ok(r, q, c) for q in chosen):
                chosen.append(r)
                if rec(chosen, i + 1):
                    return True
                chosen.pop()
        return False
    rec([], 0)
    return best

if __name__ == '__main__':
    import sys
    for plant in ('CUP', 'ANNEX', 'LAB'):
        for m in p.TOWERS:
            b = max_cells(plant, m, target=8, step=2.0)
            print(plant, m, len(b), b[:8])
